template <> inline void vector<ICoord2D>::push_back(const ICoord2D &value)
{
 if (this->_M_finish != this->_M_end_of_storage._M_data) {
  _Construct(this->_M_finish, value);
  ++this->_M_finish;
 } else {
  __false_type tag;
  _M_insert_overflow(this->_M_finish, value, tag, 1UL, true);
 }
}
